interface ExportableContract { String export(); }
abstract class ProductState {
    final String id;
    ProductState(String id) { this.id = id; }
    abstract double resolution();
}
class OrthoState extends ProductState implements ExportableContract {
    OrthoState(String id) { super(id); }
    double resolution() { return 0.05; }
    public String export() { return id + ":" + resolution(); }
}
public class AbstractVsInterfaceDemo {
    public static void main(String[] args) { System.out.println(new OrthoState("O1").export()); }
}
